import os
from fastapi import FastAPI, Request, HTTPException, Depends
from fastapi.responses import JSONResponse
from scalekit import ScalekitClient

app = FastAPI()

# Initialize Scalekit Client
# Assuming environment variables: SCALEKIT_ENVIRONMENT_URL, SCALEKIT_CLIENT_ID, SCALEKIT_CLIENT_SECRET
scalekit_client = ScalekitClient(
    env_url=os.environ.get("SCALEKIT_ENVIRONMENT_URL", ""),
    client_id=os.environ.get("SCALEKIT_CLIENT_ID", ""),
    client_secret=os.environ.get("SCALEKIT_CLIENT_SECRET", "")
)

@app.get("/.well-known/oauth-protected-resource")
async def discovery():
    env_url = os.environ.get("SCALEKIT_ENVIRONMENT_URL", "https://api.scalekit.com")
    return {
        "authorization_servers": [f"{env_url}/resources/res_123"],
        "bearer_methods_supported": ["header"],
        "resource": "https://mcp.example.com",
        "scopes_supported": ["todo:read", "todo:write"]
    }

@app.middleware("http")
async def validate_token_middleware(request: Request, call_next):
    # Skip validation for discovery endpoint
    if request.url.path == "/.well-known/oauth-protected-resource":
        return await call_next(request)

    auth_header = request.headers.get("Authorization")
    if not auth_header or not auth_header.startswith("Bearer "):
        return JSONResponse(status_code=401, content={"detail": "Missing or invalid token"})

    token = auth_header.split(" ")[1]
    try:
        # Validate token using Scalekit SDK
        validated_token = scalekit_client.validate_token(token)
        # Store validated token in request state for later use
        request.state.token = validated_token
    except Exception as e:
        return JSONResponse(status_code=401, content={"detail": f"Token validation failed: {str(e)}"})

    response = await call_next(request)
    return response

@app.post("/tools/execute")
async def execute_tool(request: Request):
    token = getattr(request.state, "token", None)
    if not token:
        raise HTTPException(status_code=401, detail="Unauthorized")

    scopes = token.get("scope", "").split(" ")
    if "todo:write" not in scopes:
        raise HTTPException(status_code=403, detail="Insufficient scope")

    return {"status": "success"}

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8080)

